import type { CommandProps } from "@tiptap/core";
import { Table as TiptapTable } from "@tiptap/extension-table";
import { TableCell } from "@tiptap/extension-table-cell";
import { TableHeader } from "@tiptap/extension-table-header";
import { TableRow } from "@tiptap/extension-table-row";

export { tableSlashCommandItem } from "./slash-command-item";

export interface TableConfigOptions {
  HTMLAttributes?: Record<string, unknown>;
  defaultCols?: number;
  defaultRows?: number;
  tableCellMinWidth?: number;
  withHeaderRow?: boolean;
  resizable?: boolean;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    tableControl: {
      insertTableWithHeader: () => ReturnType;
      moveColumn: (from: number, to: number) => ReturnType;
      moveRow: (from: number, to: number) => ReturnType;
    };
  }
}

const clampIndex = (index: number, length: number): number =>
  Math.max(0, Math.min(index, length - 1));

const findTablePosition = (doc: {
  descendants: (
    cb: (node: { type: { name: string } }, pos: number) => boolean | undefined
  ) => void;
}): number => {
  let position = -1;
  doc.descendants((node, pos) => {
    if (position !== -1 || node.type.name !== "table") {
      return position === -1;
    }
    position = pos;
    return false;
  });
  return position;
};

export const Table = TiptapTable.extend<TableConfigOptions>({
  addCommands() {
    return {
      ...this.parent?.(),
      insertTableWithHeader:
        () =>
        ({ commands }: CommandProps) =>
          commands.insertTable({
            cols: this.options.defaultCols ?? 3,
            rows: this.options.defaultRows ?? 3,
            withHeaderRow: this.options.withHeaderRow ?? true,
          }),
      moveColumn:
        (from: number, to: number) =>
        ({ dispatch, state }: CommandProps) => {
          const tablePos = findTablePosition(state.doc);
          if (tablePos === -1 || from === to) {
            return false;
          }
          const table = state.doc.nodeAt(tablePos);
          if (!table) {
            return false;
          }

          const columnCount = table.child(0)?.childCount ?? 0;
          const source = clampIndex(from, columnCount);
          const target = clampIndex(to, columnCount);
          if (source === target) {
            return false;
          }

          const rows = [];
          for (let r = 0; r < table.childCount; r += 1) {
            const row = table.child(r);
            const cells = [];
            for (let c = 0; c < row.childCount; c += 1) {
              cells.push(row.child(c));
            }
            if (cells.length === 0 || source >= cells.length) {
              rows.push(row);
              continue;
            }
            const [moved] = cells.splice(source, 1);
            if (moved === undefined) {
              rows.push(row);
              continue;
            }
            const clampedTarget = Math.min(target, cells.length);
            cells.splice(clampedTarget, 0, moved);
            rows.push(row.type.create(row.attrs, cells));
          }

          const { tr } = state;
          tr.replaceWith(
            tablePos,
            tablePos + table.nodeSize,
            table.type.create(table.attrs, rows)
          );
          dispatch?.(tr);
          return true;
        },
      moveRow:
        (from: number, to: number) =>
        ({ dispatch, state }: CommandProps) => {
          const tablePos = findTablePosition(state.doc);
          if (tablePos === -1 || from === to) {
            return false;
          }
          const table = state.doc.nodeAt(tablePos);
          if (!table) {
            return false;
          }

          const source = clampIndex(from, table.childCount);
          const target = clampIndex(to, table.childCount);
          if (source === target) {
            return false;
          }

          const rows = [];
          for (let r = 0; r < table.childCount; r += 1) {
            rows.push(table.child(r));
          }
          const [moved] = rows.splice(source, 1);
          if (moved === undefined) {
            return false;
          }
          rows.splice(target, 0, moved);

          const { tr } = state;
          tr.replaceWith(
            tablePos,
            tablePos + table.nodeSize,
            table.type.create(table.attrs, rows)
          );
          dispatch?.(tr);
          return true;
        },
    };
  },
  addExtensions() {
    return [TableRow, TableCell, TableHeader];
  },
  addOptions() {
    return {
      ...this.parent?.(),
      defaultCols: 3,
      defaultRows: 3,
      resizable: true,
      withHeaderRow: true,
    };
  },
});

"use client";

import type { ChainedCommands } from "@tiptap/core";
import {
  ArrowDownToLine,
  ArrowLeftToLine,
  ArrowRightToLine,
  ArrowUpToLine,
  CheckIcon,
  Grid2x2X,
  PanelTop,
  TableCellsMerge,
  TableCellsSplit,
  Trash2,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";

import type { ExtensionLabelKey, ExtensionLabels } from "../core/labels";
import { DropdownMenuItem } from "../ui/dropdown-item";
import { DropdownMenuSeparator } from "../ui/dropdown-separator";

export type TableCommand = (chain: ChainedCommands) => ChainedCommands;

export type TableActionId =
  | "addColumnLeft"
  | "addColumnRight"
  | "addRowAbove"
  | "addRowBelow"
  | "deleteColumn"
  | "deleteRow"
  | "deleteTable"
  | "headerRow"
  | "mergeCells"
  | "splitCell";

export interface TableAction {
  command: TableCommand;
  danger?: boolean;
  icon: LucideIcon;
  id: TableActionId;
  label: ExtensionLabelKey;
}

export const TABLE_ACTIONS: Record<TableActionId, TableAction> = {
  addColumnLeft: {
    command: (c) => c.addColumnBefore(),
    icon: ArrowLeftToLine,
    id: "addColumnLeft",
    label: "addColumnLeft",
  },
  addColumnRight: {
    command: (c) => c.addColumnAfter(),
    icon: ArrowRightToLine,
    id: "addColumnRight",
    label: "addColumnRight",
  },
  addRowAbove: {
    command: (c) => c.addRowBefore(),
    icon: ArrowUpToLine,
    id: "addRowAbove",
    label: "addRowAbove",
  },
  addRowBelow: {
    command: (c) => c.addRowAfter(),
    icon: ArrowDownToLine,
    id: "addRowBelow",
    label: "addRowBelow",
  },
  deleteColumn: {
    command: (c) => c.deleteColumn(),
    danger: true,
    icon: Trash2,
    id: "deleteColumn",
    label: "deleteColumn",
  },
  deleteRow: {
    command: (c) => c.deleteRow(),
    danger: true,
    icon: Trash2,
    id: "deleteRow",
    label: "deleteRow",
  },
  deleteTable: {
    command: (c) => c.deleteTable(),
    danger: true,
    icon: Grid2x2X,
    id: "deleteTable",
    label: "deleteTable",
  },
  headerRow: {
    command: (c) => c.toggleHeaderRow(),
    icon: PanelTop,
    id: "headerRow",
    label: "headerRow",
  },
  mergeCells: {
    command: (c) => c.mergeCells(),
    icon: TableCellsMerge,
    id: "mergeCells",
    label: "mergeCells",
  },
  splitCell: {
    command: (c) => c.splitCell(),
    icon: TableCellsSplit,
    id: "splitCell",
    label: "splitCell",
  },
};

export const ROW_ACTIONS: TableActionId[][] = [
  ["addRowAbove", "addRowBelow"],
  ["deleteRow"],
];

export const COLUMN_ACTIONS: TableActionId[][] = [
  ["addColumnLeft", "addColumnRight"],
  ["deleteColumn"],
];

export interface TableActionItemsProps {
  checked?: Partial<Record<TableActionId, boolean>>;
  disabled?: Partial<Record<TableActionId, boolean>>;
  groups: TableActionId[][];
  labels: ExtensionLabels;
  onSelect: (action: TableAction) => void;
}

export const TableActionItems = ({
  checked,
  disabled,
  groups,
  labels,
  onSelect,
}: TableActionItemsProps) =>
  groups.map((group, index) => (
    <div key={group.join(",")} className="ext-table-action-group contents">
      {index > 0 && <DropdownMenuSeparator />}
      {group.map((id) => {
        const action = TABLE_ACTIONS[id];
        const Icon = action.icon;
        const isChecked = checked?.[id];
        return (
          <DropdownMenuItem
            key={id}
            role={isChecked === undefined ? "menuitem" : "menuitemcheckbox"}
            aria-checked={isChecked}
            danger={action.danger}
            disabled={disabled?.[id]}
            onClick={() => onSelect(action)}
          >
            <Icon />
            <span className="flex-1">{labels[action.label]}</span>
            {isChecked ? <CheckIcon /> : null}
          </DropdownMenuItem>
        );
      })}
    </div>
  ));

import type { SlashCommandItem } from "../core/types";

/** Slash command item for the `@editorcn/block-editor` menu. */
export const tableSlashCommandItem: SlashCommandItem = {
  command: ({ editor, range }) => {
    if (!editor.can().insertTableWithHeader()) {
      return;
    }
    editor.chain().focus().deleteRange(range).insertTableWithHeader().run();
  },
  description: "Insert a table.",
  id: "table",
  keywords: ["table", "grid"],
  title: "Table",
};

/* Table extension styles using shadcn CSS variables */

/* ── Table node view wrapper ──
   Tiptap's Table View renders a <div class="tableWrapper"> around the
   <table>. We use it as the hover container (grips stay visible anywhere
   inside it) and as the horizontal scroll container so wide tables with
   many columns scroll instead of overflowing the content area. */
.tableWrapper {
  position: relative;
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 0.375rem;
  scrollbar-width: thin;
}

/* Columns must keep their widths when a column is added/removed. If the table
   fills the container (`width: 100%` + auto columns), the browser re-distributes
   the fixed width across more columns and they all shrink. Instead we size the
   table to its columns (`width: max-content`) so each column keeps its declared
   width and an inserted column extends the row width — the `.tableWrapper`
   scroll container above then shows the horizontal scrollbar instead. */
.tableWrapper > table {
  border-collapse: collapse;
  table-layout: fixed;
  width: max-content;
}

/* Stable default width for columns until the user resizes them (resize writes
   an inline width, which overrides this). Prevents fixed-layout auto columns
   from collapsing to 0 / splitting the table width on insert. */
.tableWrapper > table > colgroup > col {
  width: 8rem;
}

/* ── Cell borders & header row ── */
.ProseMirror table {
  border-collapse: collapse;
  margin: 0;
  overflow: hidden;
  position: relative;
}

.ProseMirror td,
.ProseMirror th {
  border: 1px solid var(--border);
  padding: 0.5rem 0.75rem;
  vertical-align: top;
  text-align: left;
  min-width: 80px;
  position: relative;
}

.ProseMirror th {
  background: var(--muted);
  font-weight: 600;
}

.ProseMirror .selectedCell {
  background: var(--accent);
}

/* ── Column resize (prosemirror-tables) ── */
.ProseMirror .column-resize-handle {
  position: absolute;
  right: -2px;
  top: 0;
  bottom: -2px;
  width: 1px;
  background-color: color-mix(in srgb, var(--foreground) 25%, transparent);
  pointer-events: none;
}

.ProseMirror .column-resize-dragging .column-resize-handle {
  background-color: var(--primary);
}

.ProseMirror.resize-cursor {
  cursor: col-resize;
}

